using System;using System.Linq;using System.Collections.Generic;
using FakeFantasyOnline.Presentation.ReferenceAssets;using UnityEngine;
class BuildingLayerContract {
 static int checks;
 static void Check(bool b,string message){checks++;if(!b)throw new Exception(message);}
 static readonly int[] Clips={432,433,435,437,438,440,442,444,445,447,449,450,452,454,455,457,459,460,462,464,465,467,469,470,472,474,476,477,479,481,482,484,486,487,489,491,492,494,496,497,499,501};
 static (ReferenceLegacyMapObjectRenderer,Texture2D,GameBootstrap,ResLoader.ObjSprite) Build(int scale=1,int dx=0,int dy=0,int dz=0,bool tile=false,string path="object/JZ/JZ_CL_0401.gso",int id=86835601,int mutateClip=-1,int frames=1,int trim=0){
  var loader=new ResLoader();ResLoader.I=loader;var tex=new Texture2D(668*scale,810*scale);var clips=(int[])Clips.Clone();if(mutateClip>=0)clips[mutateClip]++;
  var image=new ResLoader.ObjSprite{path=path,tex=tex,frames=frames,hdScale=scale,clipWidth=16,clipArr=clips,clipBy=432,nLeft=trim};loader.Images[id]=image;
  var map=new ReferenceGsmMap{Native=new GsmMap()};var obj=new GsmMap.Obj{id=id,sx=5654+dx,sy=3668+dy,xl=669,yl=811,py=4377+dy,pz=dz};if(tile)map.Native.tileObjs.Add(obj);else map.Native.libObjs.Add(obj);
  var owner=new GameBootstrap();var renderer=new ReferenceLegacyMapObjectRenderer(map,loader,new GameObject("Audit").transform,objectOwner:owner);renderer.Build();return(renderer,tex,owner,image);
 }
 static bool Covers(Sprite s,int x,int y){if(x<s.rect.x||x>=s.rect.x+s.rect.width)return false;float localX=x-s.rect.x,localY=s.rect.height-y-.5f;if(s.vertices==null)return localY>=0&&localY<s.rect.height;for(int k=0;k<s.vertices.Length;k+=4){var q=s.vertices.Skip(k).Take(4);if(localX+.5>=q.Min(v=>v.x)&&localX+.5<q.Max(v=>v.x)&&localY>=q.Min(v=>v.y)&&localY<q.Max(v=>v.y))return true;}return false;}
 static int Order(ReferenceLegacyMapObjectRenderer r,int x,int y){var at=r.Rendered.Where(s=>Covers(s.sprite,x,y)).ToArray();Check(at.Length==1,"one source pixel exactly once at probe");return at[0].sortingOrder;}
 static void Coverage(int scale){var(r,tex,owner,image)=Build(scale);var seen=new byte[tex.width*tex.height];foreach(var sr in r.Rendered){var s=sr.sprite;Check(s.texture==tex,"borrow the original texture, never copied pixels");Check(s.ppu==100*scale,"native PPU preserved");int x0=(int)s.rect.x;var quads=new List<float[]>();if(s.vertices==null)quads.Add(new[]{0f,0f,s.rect.width,s.rect.height});else for(int k=0;k<s.vertices.Length;k+=4){var q=s.vertices.Skip(k).Take(4);quads.Add(new[]{q.Min(v=>v.x),q.Min(v=>v.y),q.Max(v=>v.x),q.Max(v=>v.y)});}foreach(var q in quads)for(int y=(int)q[1];y<(int)q[3];y++)for(int x=(int)q[0];x<(int)q[2];x++)seen[y*tex.width+x0+x]++;}
  Check(owner.FadeCalls==1&&owner.FadeGroup.Count==r.Rendered.Count&&owner.FadeOrder==r.Rendered.Max(sr=>sr.sortingOrder),"native fade receives entire group and max actual depth");
  Check(r.Rendered.Count<=50,"same-depth geometry merged to bounded renderer count");
  Check(seen.All(v=>v==1),"exact complementary texture partition, no gaps/duplicates");
  foreach(var pt in new[]{(350,390),(450,340),(550,290)})Check(Order(r,pt.Item1*scale,pt.Item2*scale)<3668+pt.Item2+1,"reachable board is behind the actor (live dispatch)");
  var native=owner.GetObjectSlicesForIndependentRuntime(86835601,image,100);foreach(int x in new[]{225,350,450,550,645}){var old=native.Single(s=>x*scale>=s.Item1.rect.x&&x*scale<s.Item1.rect.x+s.Item1.rect.width);Check(Order(r,x*scale,600*scale)==3668+old.Item3,"front rail/poles retain exact authored depth");}
  Check(Order(r,350*scale,215*scale)>3668+215+1,"rear canopy still hides an actor behind it");r.Dispose();
 }
 static void Main(string[] args){foreach(int s in new[]{1,2,4})Coverage(s);var(a,_,__,___)=Build();var(b,____,_____,______)=Build(dx:137,dy:211,dz:61);Check(a.Rendered.Count==b.Rendered.Count,"translated same art stable partition");for(int i=0;i<a.Rendered.Count;i++){Check(b.Rendered[i].sortingOrder==a.Rendered[i].sortingOrder+211||b.Rendered[i].sortingOrder==a.Rendered[i].sortingOrder+150,"native front depth or projected rear-plane depth");Check(b.Placements[i].ScreenX==a.Placements[i].ScreenX+137&&b.Placements[i].ScreenY==a.Placements[i].ScreenY+150,"native visual pz projection preserved");}a.Dispose();b.Dispose();
  foreach(var p in new[]{(2141,-749,515,290),(2720,-110,485,275)}){var(rr,tx,ow,imm)=Build(dx:p.Item1,dy:p.Item2,dz:144);Check(Order(rr,p.Item3,p.Item4)<3668+p.Item2+p.Item4-144+1,"raised original map copy rear plane stays behind its real projected actor");rr.Dispose();}

  var(negativeZ,nt,no,ni)=Build(dz:-400);var nativeNegative=no.GetObjectSlicesForIndependentRuntime(86835601,ni,100);foreach(int x in new[]{225,350,450,550,645}){var old=nativeNegative.Single(s=>x>=s.Item1.rect.x&&x<s.Item1.rect.x+s.Item1.rect.width);Check(Order(negativeZ,x,250)<=3668+old.Item3,"negative elevation never promotes support above original order");}negativeZ.Dispose();
  foreach(var which in new[]{0,1,2,3,4,5}){GameBootstrap.UseIsoY=which==5;var(r,t,o,im)=which==0?Build(path:"object/JZ/other.gso"):which==1?Build(id:86835602):which==2?Build(mutateClip:20):which==3?Build(trim:1):which==4?Build(tile:true):Build();Check(r.Rendered.All(s=>s.sprite.vertices==null),"unreviewed path/id/clip/trim/tile/alternate shader retains native art");if(which!=4)Check(Order(r,350,390)>4059,"unreviewed input does not receive an accidental repair");r.Dispose();GameBootstrap.UseIsoY=false;}
  var(animated,tt,oo,ii)=Build(frames:2);Check(animated.Rendered.Count==1&&animated.Rendered[0].sprite.vertices==null,"animated model retains native animation branch");animated.Dispose();Console.WriteLine("PASS "+checks+" live-dispatch building contracts (Unity substitutes, not a Unity Player run)");BuildingSupportContract.Run(args[0]);BuildingMixedPzContract.Run(args[0]);BuildingStaticContract.Run(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(args[0]),"BuildingStaticCases.json"));BuildingAuthoredContract.Run(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(args[0]),"BuildingAuthoredCases.json"));
 }
}
